# Remove Microsoft Teams (Consumer) Write-Host "Removing Microsoft Teams (Consumer)..." -ForegroundColor Cyan # Remove Teams AppX package Get-AppxPackage -Name "MicrosoftTeams" -ErrorAction SilentlyContinue | Remove-AppxPackage -ErrorAction SilentlyContinue Get-AppxPackage -Name "MSTeams" -ErrorAction SilentlyContinue | Remove-AppxPackage -ErrorAction SilentlyContinue # Also remove the chat icon from taskbar Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "TaskbarMn" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Prevent Teams from reinstalling Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent" -Name "DisableConsumerTeams" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Write-Host "Microsoft Teams (Consumer) has been removed." -ForegroundColor Green